option = {
  radar: {
    indicator: [
      { name: 'A', max: 100 },
      { name: 'B', max: 100 },
      { name: 'C', max: 100 },
      { name: 'D', max: 100 },
      { name: 'E', max: 100 }
    ]
  },
  series: [{
    type: 'radar',
    data: [{ value: [80, 90, 70, 60, 50] }]
  }, {
    type: 'custom',
    renderItem: function (params, api) {
      const coords = [];
      const data = api.value(0) || [80, 90, 70, 60, 50];

      // Get coordinates of radar points
      for (let i = 0; i < data.length; i++) {
        coords.push(api.coord([i, data[i]]));
      }

      // Create a rounded path
      const path = [];
      const radius = 10; // Adjust corner radius
      for (let i = 0; i < coords.length; i++) {
        const curr = coords[i];
        const next = coords[(i + 1) % coords.length];
        const prev = coords[(i - 1 + coords.length) % coords.length];

        // Calculate control points for rounded corners
        // (This is a simplified example; you'll need proper vector math)
        path.push(['M', prev.x, prev.y]);
        path.push(['Q', curr.x, curr.y, next.x, next.y]); // Quadratic Bézier
      }

      return {
        type: 'path',
        shape: { path },
        style: { stroke: 'red', fill: 'none' }
      };
    },
    data: [{}]
  }]
};

