public static class AutoMapperExtensions
{
    public static IServiceCollection AddCustomAutoMapper(this IServiceCollection services, Assembly assembly)
    {
        // Find all types that implement IMapperProfile
        var profileTypes = assembly.GetTypes()
            .Where(t => typeof(IMapperProfile).IsAssignableFrom(t) && !t.IsInterface && !t.IsAbstract);

        // Create instances of each profile and configure AutoMapper
        var profiles = profileTypes.Select(Activator.CreateInstance).Cast<IMapperProfile>();

        var config = new MapperConfiguration(cfg =>
        {
            foreach (var profile in profiles)
            {
                profile.ConfigureMapping(cfg);
            }
        });

        // Register IMapper
        services.AddSingleton(config.CreateMapper());

        return services;
    }
}

